{"query":"{
     taskDetails(
     from: {{goback_by_a_day}}
     to:{{currentTime}} 

filter: {
      and: [
        {
          or: [
            { origin: { equals: "{{NewPhoneContact.ANI}}" } }
            { origin: { equals: "{{ANITrim}}" } }
          ]
        }
        { isActive: { equals: true } } # Example of an additional filter in the AND clause
      ]
    }
  )
            {   
                tasks {
                   id
                   isActive
                    callbackData{
                      callbackStatus
                      callbackOrigin
                      callbackNumber 
                    }    
                    }  
            }
}","variables":{}}

